-- View current statistics on a table
EXEC sp_helpstats 'dbo.Orders', 'ALL';

-- Display detailed statistics information
DBCC SHOW_STATISTICS('dbo.Orders', 'IX_Orders_OrderDate') WITH HISTOGRAM;

-- Update statistics with a full scan (most accurate)
UPDATE STATISTICS dbo.Orders IX_Orders_OrderDate WITH FULLSCAN;

-- Update all statistics on a table
UPDATE STATISTICS dbo.Orders WITH FULLSCAN;

-- Enable auto update statistics at the database level
ALTER DATABASE [YourDB] SET AUTO_UPDATE_STATISTICS ON;

-- Enable async auto update (prevents query blocking during stats update)
ALTER DATABASE [YourDB] SET AUTO_UPDATE_STATISTICS_ASYNC ON;
